  var session=m.sessions.get();if(session.admission()!=a)deny();var observed=supervisor.requireModelRequest(session,m.observation);var state=contexts.require(session,m.price);m.executable.requireCurrent(a);var history=histories.ordered(session,observed.ordinal());var historySend=history.requireModelSend(state.model().required("definition").required("provider").asText());var send=(ObjectNode)state.send().deepCopy();send.set("tool_history",historySend);var dependencies=(ObjectNode)state.dependencies().deepCopy();dependencies.set("send_authorizations",send);state=new FormalEvaluationInvocationContext.State(state.model(),state.request(),dependencies,send,state.body(),state.price());var exact=requireProjection(session,observed,state,history.data());if(!Arrays.equals(m.bytes,ContentReadAuthorization.canonicalBytes(exact))||!m.tokens.inputSha256().equals(WireValues.sha256(m.bytes))||!tokenizer.configuredSourceBasis().equals(new PermissionProtocol.Basis(m.tokens.tokenizerVersion(),m.tokens.executableSha256())))bad();
